from datetime import datetime


# Symbolic constants for time format
TIME_FORMAT = '%H:%M'


class Classroom:
    def __init__(self, id):
        self._id = id
        self._courses = []

    @property
    def id(self):
        return self._id

    @property
    def courses(self):
        """Encapsulate Collection: returns a tuple to prevent modification of the internal list."""
        return tuple(self._courses)

    def add_course(self, course):
        if course not in self._courses:
            self._courses.append(course)

    def remove_course(self, course):
        if course in self._courses:
            self._courses.remove(course)

    def _parse_time(self, time_str):
        """Extract Method: extracts time parsing logic."""
        return datetime.strptime(time_str, TIME_FORMAT)

    def is_free_at(self, check_time):
        check_datetime = self._parse_time(check_time)

        for course in self._courses:
            course_start = self._parse_time(course['start_time'])
            course_end = self._parse_time(course['end_time'])
            if course_start <= check_datetime <= course_end:
                return False
        return True

    def check_course_conflict(self, new_course):
        new_start_time = self._parse_time(new_course['start_time'])
        new_end_time = self._parse_time(new_course['end_time'])

        for course in self._courses:
            start_time = self._parse_time(course['start_time'])
            end_time = self._parse_time(course['end_time'])

            # Replace Nested Conditional with Guard Clauses / Remove Control Flag
            # If any conflict is found, return False immediately
            if (start_time <= new_start_time <= end_time) or (start_time <= new_end_time <= end_time):
                return False

        return True
